"""Extract blueprint \\leanok marks, statement-level and proof-level, separately.

Independent of the published recipe: environments are matched with an explicit
stack (so a nested env cannot make a non-greedy regex reach past the true
\\end{...}), and `%` comments are stripped honouring backslash escapes.
"""
import re, glob, json, sys

ENVS = {'theorem', 'lemma', 'proposition', 'corollary', 'definition', 'remark',
        'example', 'notation', 'convention'}

def strip_comments(t):
    out = []
    for line in t.split('\n'):
        i, n = 0, len(line)
        while i < n:
            if line[i] == '\\':
                i += 2
                continue
            if line[i] == '%':
                line = line[:i]
                break
            i += 1
        out.append(line)
    return '\n'.join(out)

TOK = re.compile(r'\\(begin|end)\{([^}]*)\}')

def top_level_envs(t):
    """Yield (name, inner_start, inner_end, outer_start, outer_end) for every
    environment at nesting depth 0."""
    stack = []
    for m in TOK.finditer(t):
        kind, name = m.group(1), m.group(2)
        if kind == 'begin':
            stack.append((name, m.end(), m.start()))
        else:
            # pop until the matching name (tolerates malformed nesting)
            while stack:
                nm, inner_start, outer_start = stack.pop()
                if nm == name:
                    if not stack:
                        yield (nm, inner_start, m.start(), outer_start, m.end())
                    break

stmt_marks, proof_marks = [], []
n_stmt_nodes = n_proof_envs = n_attributed = 0
orphan_proofs = []

for fn in sorted(glob.glob('blueprint/src/chapters/*.tex')):
    t = strip_comments(open(fn).read())
    envs = list(top_level_envs(t))
    for idx, (name, s, e, os_, oe) in enumerate(envs):
        if name not in ENVS:
            continue
        body = t[s:e]
        lab = re.search(r'\\label\{([^}]*)\}', body)
        lean = re.search(r'\\lean\{([^}]*)\}', body)
        if not (lab and lean):
            continue
        n_stmt_nodes += 1
        pins = [x.strip() for x in lean.group(1).split(',') if x.strip()]
        label = lab.group(1)
        base = fn.split('/')[-1]
        # statement-level mark: \leanok inside the statement environment itself
        if '\\leanok' in body:
            for d in pins:
                stmt_marks.append((base, label, d))
        # proof-level mark: the NEXT top-level environment, if it is a proof
        if idx + 1 < len(envs) and envs[idx + 1][0] == 'proof':
            pname, ps, pe, pos, poe = envs[idx + 1]
            gap = t[oe:pos].strip()
            if gap:
                print(f'NONBLANK GAP {base}:{label}: {gap[:80]!r}', file=sys.stderr)
            if '\\leanok' in t[ps:pe]:
                n_attributed += 1
                for d in pins:
                    proof_marks.append((base, label, d))

    for (name, s, e, os_, oe) in envs:
        if name == 'proof':
            n_proof_envs += 1 if '\\leanok' in t[s:e] else 0

json.dump({'stmt': stmt_marks, 'proof': proof_marks},
          open('/tmp/marks.json', 'w'))
sp = {d for _, _, d in stmt_marks}
pp = {d for _, _, d in proof_marks}
print(f'{n_stmt_nodes} statement nodes with \\label+\\lean')
print(f'statement-level: {len(stmt_marks)} marks pinning {len(sp)} distinct declarations')
print(f'proof-level:     {len(proof_marks)} marks pinning {len(pp)} distinct declarations')
print(f'top-level proof envs carrying \\leanok: {n_proof_envs}; attributed to a node: {n_attributed}')
with open('/tmp/all_pins.txt', 'w') as f:
    for d in sorted(sp | pp):
        f.write(d + '\n')
print(f'union: {len(sp | pp)} distinct declarations to probe')
